template <typename UnionPtrType>
Camera3NotifyMsgMessagePtr Camera3NotifyMsgMessage::Clone() const {
  // Use UnionPtrType to prevent the compiler from trying to compile this
  // without being asked.
  UnionPtrType rv(New());
  switch (tag_) {
    case Tag::ERROR:
      rv->set_error(mojo::Clone(*data_.error));
      break;
    case Tag::SHUTTER:
      rv->set_shutter(mojo::Clone(*data_.shutter));
      break;
    case Tag::GENERIC:
      rv->set_generic(mojo::Clone(*data_.generic));
      break;
  }
  return rv;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, Camera3NotifyMsgMessage>::value>::type*>
bool Camera3NotifyMsgMessage::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::ERROR:
      return mojo::Equals(*(data_.error), *(other.data_.error));
    case Tag::SHUTTER:
      return mojo::Equals(*(data_.shutter), *(other.data_.shutter));
    case Tag::GENERIC:
      return mojo::Equals(*(data_.generic), *(other.data_.generic));
  }

  return false;
}
